let current='ko';
try{const q=new URLSearchParams(location.search).get('lang');current=['ko','zh','en'].includes(q)?q:localStorage.getItem('siseon-language')||'ko';}catch{}
if(!copy[current])current='ko';
export const lang=()=>current;
export const t=key=>copy[current][key]??copy.ko[key]??key;
export function setLanguage(next){if(!copy[next])return;current=next;document.documentElement.lang=next==='zh'?'zh-CN':next;document.title=t('title');try{localStorage.setItem('siseon-language',next);const url=new URL(location.href);url.searchParams.set('lang',next);history.replaceState(null,'',url);}catch{}}
